void log_boot(uint64_t t_us) {
    // two 32-bit halves, works with newlib-nano
    printf("boot at 0x%08lx%08lx us\n",
           (unsigned long)(t_us >> 32),
           (unsigned long)(t_us & 0xFFFFFFFFu));
}

