#[interrupt]
fn USART1() {
    critical_section::with(|cs| {
        if let Some(uart) = UART.borrow(cs).borrow_mut().as_mut() {
            let b = uart.read_byte();
            RX.borrow(cs).borrow_mut().push(b);
        }
    });
}

